CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','employee')),status TEXT NOT NULL CHECK(status IN ('active','disabled')),must_change_password INTEGER NOT NULL CHECK(must_change_password IN (0,1)),revision INTEGER NOT NULL CHECK(revision>=1),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL) STRICT;
CREATE INDEX users_status ON users(status,username);
CREATE TABLE groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,name_key TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL CHECK(revision>=1),created_at INTEGER NOT NULL) STRICT;
CREATE TABLE group_members(group_id TEXT NOT NULL REFERENCES groups(id),user_id TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,PRIMARY KEY(group_id,user_id)) STRICT;
CREATE INDEX membership_user ON group_members(user_id,group_id);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('personal','team','office')),name TEXT NOT NULL,owner_user_id TEXT REFERENCES users(id),group_id TEXT REFERENCES groups(id),member_permission TEXT CHECK(member_permission IN ('viewer','editor')),root_id TEXT REFERENCES nodes(id) DEFERRABLE INITIALLY DEFERRED,revision INTEGER NOT NULL CHECK(revision>=1),created_at INTEGER NOT NULL,CHECK((kind='personal' AND owner_user_id IS NOT NULL AND group_id IS NULL AND member_permission IS NULL) OR (kind='team' AND group_id IS NOT NULL AND owner_user_id IS NULL AND member_permission IS NOT NULL) OR (kind='office' AND owner_user_id IS NULL AND group_id IS NULL AND member_permission='viewer'))) STRICT;
CREATE UNIQUE INDEX office_singleton ON workspaces(kind) WHERE kind='office';
CREATE UNIQUE INDEX personal_owner ON workspaces(owner_user_id) WHERE kind='personal';
CREATE UNIQUE INDEX team_group ON workspaces(group_id) WHERE kind='team';
CREATE TABLE nodes(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),parent_id TEXT REFERENCES nodes(id) ON DELETE SET NULL,kind TEXT NOT NULL CHECK(kind IN ('folder','file')),name TEXT NOT NULL,name_key TEXT NOT NULL,size_bytes INTEGER CHECK(size_bytes>=0),mime_type TEXT,manifest_sha256 TEXT,blob_key TEXT,revision INTEGER NOT NULL CHECK(revision>=1),state TEXT NOT NULL CHECK(state IN ('ACTIVE','TRASHED','PURGING')),created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,modified_at INTEGER NOT NULL,deleted_at INTEGER,deleted_by TEXT REFERENCES users(id),restore_parent_id TEXT REFERENCES nodes(id) ON DELETE SET NULL,CHECK((kind='folder' AND size_bytes IS NULL AND mime_type IS NULL AND manifest_sha256 IS NULL AND blob_key IS NULL) OR (kind='file' AND size_bytes IS NOT NULL AND mime_type IS NOT NULL AND manifest_sha256 IS NOT NULL AND blob_key IS NOT NULL))) STRICT;
CREATE UNIQUE INDEX sibling_name ON nodes(parent_id,name_key) WHERE state='ACTIVE';
CREATE INDEX nodes_browse ON nodes(workspace_id,parent_id,state,name_key,id);
CREATE INDEX nodes_modified ON nodes(workspace_id,modified_at,id);
CREATE INDEX nodes_deleted ON nodes(deleted_at,id);
CREATE TABLE node_closure(ancestor_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,descendant_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,depth INTEGER NOT NULL CHECK(depth>=0 AND depth<=64),PRIMARY KEY(ancestor_id,descendant_id)) STRICT;
CREATE INDEX closure_desc ON node_closure(descendant_id,ancestor_id);
CREATE TABLE grants(node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,principal_type TEXT NOT NULL CHECK(principal_type IN ('user','group')),principal_id TEXT NOT NULL,permission TEXT NOT NULL CHECK(permission IN ('viewer','editor')),created_at INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(node_id,principal_type,principal_id)) STRICT;
CREATE INDEX grants_principal ON grants(principal_type,principal_id,node_id);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf_token TEXT NOT NULL,created_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,password_change_only INTEGER NOT NULL CHECK(password_change_only IN (0,1))) STRICT;
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE uploads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),parent_id TEXT NOT NULL REFERENCES nodes(id),name TEXT NOT NULL,name_key TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),offset_bytes INTEGER NOT NULL CHECK(offset_bytes>=0 AND offset_bytes<=size_bytes),last_modified_ms INTEGER NOT NULL CHECK(last_modified_ms>=0),state TEXT NOT NULL CHECK(state IN ('OPEN','COMMITTING','COMPLETE','CANCELLED','EXPIRED','FAILED')),reserved_node_id TEXT NOT NULL UNIQUE,node_id TEXT REFERENCES nodes(id) ON DELETE SET NULL,staging_key TEXT NOT NULL UNIQUE,manifest_sha256 TEXT,created_at INTEGER NOT NULL,last_activity_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,error_code TEXT) STRICT;
CREATE UNIQUE INDEX upload_name ON uploads(parent_id,name_key) WHERE state IN ('OPEN','COMMITTING');
CREATE INDEX uploads_user ON uploads(user_id,state);
CREATE INDEX uploads_expiry ON uploads(expires_at);
CREATE TABLE upload_chunks(upload_id TEXT NOT NULL REFERENCES uploads(id) ON DELETE CASCADE,offset_bytes INTEGER NOT NULL CHECK(offset_bytes>=0),size_bytes INTEGER NOT NULL CHECK(size_bytes>0 AND size_bytes<=8388608),sha256 TEXT NOT NULL,PRIMARY KEY(upload_id,offset_bytes)) STRICT;
CREATE TABLE audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT,at INTEGER NOT NULL,request_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('success','denied','failed')),admin_override INTEGER NOT NULL CHECK(admin_override IN (0,1)),ip TEXT NOT NULL,detail_json TEXT NOT NULL CHECK(json_valid(detail_json) AND length(detail_json)<=2048)) STRICT;
CREATE INDEX audit_at ON audit_events(at,id);
CREATE INDEX audit_actor ON audit_events(actor_id,at);
CREATE INDEX audit_action ON audit_events(action,at);
CREATE TABLE idempotency(actor_id TEXT NOT NULL REFERENCES users(id),method TEXT NOT NULL,path TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('PENDING','DONE')),response_status INTEGER,response_json TEXT,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(actor_id,method,path,key)) STRICT;
CREATE TABLE fs_intents(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('COMMIT_UPLOAD','PURGE_SUBTREE','CLEAN_UPLOAD')),subject_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('PENDING','RUNNING','DONE','FAILED')),attempts INTEGER NOT NULL CHECK(attempts>=0),next_attempt_at INTEGER NOT NULL,last_error TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(kind,subject_id)) STRICT;
CREATE INDEX intents_pending ON fs_intents(state,next_attempt_at);
CREATE TABLE app_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY,sha256 TEXT NOT NULL,applied_at INTEGER NOT NULL) STRICT;
